const taskForm = reactive({ task_type: 'water', greenhouse_id: 1, planned_date: new Date().toISOString().slice(0, 10), title: '' });
const irrForm = reactive({ greenhouse_id: 1, amount_l: 100, method: '滴灌', note: '' });
const notifyCfg = reactive({ webhook_url: '', smtp: { host: '', port: 465, username: '', password: '', sender: '', recipients: '', use_tls: true } });
const notifyTestMsg = ref('');
const notifyTestOk = ref(false);
