input.old_string:
const resolveAlert = async (id) => {
  await api(`/api/alerts/${id}/resolve`, { method: 'POST' });
  refresh();
};

input.new_string:
const openHandle = (a, isResolve) => {
  Object.assign(handleModal, {
    show: true, id: a.id, isResolve,
    message: `${a.greenhouse_name} · ${a.message}`,
    handler: a.handler || '', note: a.handle_note || '',
  });
};
const submitHandle = async () => {
  const body = { handler: handleModal.handler, note: handleModal.note };
  if (handleModal.isResolve) {
    await api(`/api/alerts/${handleModal.id}/resolve`, { method: 'POST', body });
  } else {
    await api(`/api/alerts/${handleModal.id}/handle`, { method: 'PATCH', body });
  }
  handleModal.show = false;
  refresh();
};
const loadNotifyConfig = async () => {
  const cfg = await api('/api/notify/config');
  notifyCfg.webhook_url = cfg.webhook_url;
  Object.assign(notifyCfg.smtp, cfg.smtp);
};
const saveNotifyConfig = async () => {
  await api('/api/notify/config', { method: 'PUT', body: notifyCfg });
  notifyTestOk.value = true;
  notifyTestMsg.value = '配置已保存';
};
const testNotify = async () => {
  await saveNotifyConfig();
  const r = await api('/api/notify/test', { method: 'POST' });
  notifyTestOk.value = r.status === 'sent';
  notifyTestMsg.value = r.status === 'sent' ? '✅ 测试通知已送达'
    : r.status === 'none' ? '未配置任何外部渠道' : `❌ 推送失败：${r.error}`;
};

